header.script:

document.addEventListener('click', function (ev) {
    // 1. Open Menu button clicked
    var menuBtn = ev.target.closest('.wbl-menu-btn, .wbl-header-menu-btn');
    if (menuBtn) {
        ev.preventDefault();
        console.log('Menu button clicked (Vanilla JS)');
        var sidebar = document.getElementById('wbl_sidebar');
        var overlay = document.getElementById('wbl_sidebar_overlay');
        if (sidebar) sidebar.classList.add('wbl-sidebar-open');
        if (overlay) {
            overlay.style.display = 'block';
            setTimeout(function() {
                overlay.classList.add('wbl-sidebar-open');
            }, 10);
        }
        document.body.style.overflow = 'hidden';
        return;
    }

    // 2. Close Menu button or overlay clicked
    var closeBtn = ev.target.closest('#wbl_close_sidebar, #wbl_sidebar_overlay');
    if (closeBtn) {
        ev.preventDefault();
        console.log('Close button/overlay clicked (Vanilla JS)');
        var sidebar = document.getElementById('wbl_sidebar');
        var overlay = document.getElementById('wbl_sidebar_overlay');
        if (sidebar) sidebar.classList.remove('wbl-sidebar-open');
        if (overlay) {
            overlay.classList.remove('wbl-sidebar-open');
            setTimeout(function() {
                overlay.style.display = 'none';
             }, 300); // Matches transition duration
         }
         document.body.style.overflow = '';
         return;
     }

    // 3. "Comprar" button clicked on product grid cards
      var comprarBtn = ev.target.closest('.custom-comprar-btn');
      if (comprarBtn) {
          ev.preventDefault();
          ev.stopPropagation();
          if (comprarBtn.classList.contains('disabled')) return;

          var form = comprarBtn.closest('form');
          if (!form) return;

          var productIdInput = form.querySelector('input[name="product_id"]');
          if (!productIdInput) return;

          var productId = productIdInput.value;
          if (!productId) return;

          // Disable button to prevent double-click
          comprarBtn.classList.add('disabled');
          comprarBtn.style.opacity = '0.7';
          comprarBtn._originalHTML = comprarBtn.innerHTML;

          // Extract product details instantly
          var card = comprarBtn.closest('.oe_product_cart') || comprarBtn.closest('.oe_product');
          var name = card ? (card.querySelector('.o_wsale_products_item_title a') ? card.querySelector('.o_wsale_products_item_title a').textContent.trim() : 'Producto') : 'Producto';
          var imgEl = card ? card.querySelector('.oe_product_image img') : null;
          var imgUrl = imgEl ? (imgEl.getAttribute('data-src') || imgEl.getAttribute('src') || '') : '';
          var priceEl = card ? card.querySelector('.product_price') : null;
          var priceText = 'S/ 0.00';
          var oldPriceText = '';
          var discountPercent = 0;
          if (priceEl) {
              var tempDiv = priceEl.cloneNode(true);
              var removeHiddenTags = function(container) {
                  var allChildren = container.querySelectorAll('*');
                  allChildren.forEach(function(el) {
                      var style = el.getAttribute('style') || '';
                      if (style.replace(/\s/g, '').indexOf('display:none') !== -1 || el.hasAttribute('itemprop')) {
                          el.remove();
                      }
                  });
              };

              var delEl = tempDiv.querySelector('del');
              if (delEl) {
                  removeHiddenTags(delEl);
                  oldPriceText = delEl.textContent.trim();
                  delEl.remove();
              }

              removeHiddenTags(tempDiv);
              priceText = tempDiv.textContent.trim();

              if (oldPriceText && oldPriceText !== priceText) {
                  var oldP = parseFloat(oldPriceText.replace(/[^\d.]/g, '')) || 0;
                  var newP = parseFloat(priceText.replace(/[^\d.]/g, '')) || 0;
                  if (oldP > newP) {
                      discountPercent = Math.round((1 - newP / oldP) * 100);
                  }
              }
          }

          var brand = 'WANKA';
          var commonBrands = ['GLORIA', 'LAIVE', 'NESTLE', 'DONOFRIO', 'ALICORP', 'BOLIVAR', 'OPAL', 'MIMOSA', 'PRIMOR', 'SAN FERNANDO', 'RED BULL', 'COCA COLA', 'INCA KOLA', 'PEPSI'];
          var upperName = name.toUpperCase();
          for (var i = 0; i < commonBrands.length; i++) {
              if (upperName.indexOf(commonBrands[i]) !== -1) {
                  brand = commonBrands[i];
                  break;
              }
          }
          if (brand === 'WANKA' && name) {
              var words = name.split(' ');
              if (words.length > 0 && words[0].length > 3) {
                  brand = words[0].toUpperCase();
              }
          }

          var details = {
              name: name,
              imgUrl: imgUrl,
              priceText: priceText,
              oldPriceText: oldPriceText,
              discountPercent: discountPercent,
              brand: brand
          };

          // Trigger optimistic add to cart and show modal instantly
          addToCartAndShowModalOptimistic(productId, 1, details, comprarBtn, form);
          return;
      }

     // 3.5. "Añadir al carrito" button clicked on product detail page
     var addToCartBtn = ev.target.closest('#add_to_cart');
     if (addToCartBtn) {
         ev.preventDefault();
         ev.stopPropagation();
         if (addToCartBtn.classList.contains('disabled')) return;

         var form = addToCartBtn.closest('form');
         if (!form) return;

         var productIdInput = form.querySelector('input[name="product_id"]');
         if (!productIdInput) return;

         var productId = productIdInput.value;
         if (!productId) return;

         // Read quantity
         var qtyInput = form.querySelector('input[name="add_qty"]') || form.querySelector('.quantity');
         var addQty = qtyInput ? parseInt(qtyInput.value) : 1;
         if (isNaN(addQty) || addQty < 1) addQty = 1;

         // Disable button
         addToCartBtn.classList.add('disabled');
         addToCartBtn.style.opacity = '0.7';
         addToCartBtn._originalHTML = addToCartBtn.innerHTML;

         // Extract product details instantly
         var nameEl = document.querySelector('h1[t-field="product.name"]') || document.querySelector('.js_product h1') || document.querySelector('h1');
         var name = nameEl ? nameEl.textContent.trim() : 'Producto';

         var imgEl = document.querySelector('#o-carousel-product .carousel-item.active img') || 
                     document.querySelector('#o-carousel-product img') || 
                     document.querySelector('.product_detail_img') || 
                     document.querySelector('span[t-field="product.image_1920"] img');
         var imgUrl = imgEl ? (imgEl.getAttribute('data-src') || imgEl.getAttribute('src') || '') : '';

         var priceText = '';
         var priceValueEl = document.querySelector('.oe_price_value');
         if (priceValueEl) {
             var priceParent = priceValueEl.closest('.oe_price') || priceValueEl.parentElement;
             var currencyEl = priceParent ? (priceParent.querySelector('.oe_currency_value') || priceParent.querySelector('.currency')) : null;
             var currency = currencyEl ? currencyEl.textContent.trim() : 'S/';
             priceText = currency + ' ' + priceValueEl.textContent.trim();
         } else {
             var priceEl = document.querySelector('.product_price .oe_price') || document.querySelector('.oe_price');
             priceText = priceEl ? priceEl.textContent.trim() : 'S/ 0.00';
         }

         var brand = 'WANKA';
         var commonBrands = ['GLORIA', 'LAIVE', 'NESTLE', 'DONOFRIO', 'ALICORP', 'BOLIVAR', 'OPAL', 'MIMOSA', 'PRIMOR', 'SAN FERNANDO', 'RED BULL', 'COCA COLA', 'INCA KOLA', 'PEPSI'];
         var upperName = name.toUpperCase();
         for (var i = 0; i < commonBrands.length; i++) {
             if (upperName.indexOf(commonBrands[i]) !== -1) {
                 brand = commonBrands[i];
                 break;
             }
         }
         if (brand === 'WANKA' && name) {
             var words = name.split(' ');
             if (words.length > 0 && words[0].length > 3) {
                 brand = words[0].toUpperCase();
             }
         }

         var details = {
             name: name,
             imgUrl: imgUrl,
             priceText: priceText,
             brand: brand
         };

         // Trigger optimistic add to cart and show modal instantly
         addToCartAndShowModalOptimistic(productId, addQty, details, addToCartBtn, form);
         return;
     }           
});

// 3. Category hover on desktop (min-width: 768px)
document.addEventListener('mouseover', function(ev) {
    var menuItem = ev.target.closest('.wbl-mega-menu-item');
    if (menuItem && window.innerWidth >= 768) {
        var categoryId = menuItem.getAttribute('data-category-id');
        if (categoryId) {
            // Deactivate all items
            var allItems = document.querySelectorAll('.wbl-mega-menu-item');
            allItems.forEach(function(item) {
                item.classList.remove('active');
            });
            menuItem.classList.add('active');

            // Deactivate all panels
            var allPanels = document.querySelectorAll('.wbl-category-panel');
            allPanels.forEach(function(panel) {
                panel.classList.remove('active');
                panel.style.display = 'none';
            });

            // Activate target panel
            var targetPanel = document.getElementById('wbl-category-panel-' + categoryId);
            if (targetPanel) {
                targetPanel.classList.add('active');
                targetPanel.style.display = 'block';
            }
        }
    }
});

// 4. Modal plus/minus button event handlers (delegated)
document.addEventListener('click', function(ev) {
    var btnPlus = ev.target.closest('#modal-qty-plus');
    var btnMinus = ev.target.closest('#modal-qty-minus');
    if (btnPlus || btnMinus) {
        ev.preventDefault();
        var modalEl = document.getElementById('cartSuccessModal');
        var productId = modalEl.getAttribute('data-product-id');
        if (!productId) return;

        var qtyInput = document.getElementById('modal-qty-input');
        var delta = btnPlus ? 1 : -1;

        // Prevent going below 0
        var currentQty = parseInt(qtyInput.value) || 0;
        if (delta === -1 && currentQty <= 0) return;

        updateModalQtyHelper(productId, delta);
    }
});

function updateModalQtyHelper(productId, delta) {
    var modalEl = document.getElementById('cartSuccessModal');
    var qtyInput = document.getElementById('modal-qty-input');
    var btnMinus = document.getElementById('modal-qty-minus');
    var btnPlus = document.getElementById('modal-qty-plus');

    btnMinus.style.pointerEvents = 'none';
    btnPlus.style.pointerEvents = 'none';
    qtyInput.style.opacity = '0.5';

    fetch('/shop/cart/update_json', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            params: {
                product_id: parseInt(productId),
                add_qty: delta
            }
        })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        btnMinus.style.pointerEvents = '';
        btnPlus.style.pointerEvents = '';
        qtyInput.style.opacity = '';

        if (data && data.result && typeof data.result.quantity !== 'undefined') {
            var newQty = data.result.quantity;
            qtyInput.value = newQty;

            // Update cart badge quantity in header
            var qtyBadges = document.querySelectorAll('.my-cart-qty');
            var newTotalQty = typeof data.result.cart_quantity !== 'undefined' ? data.result.cart_quantity : 0;
            qtyBadges.forEach(function(badge) {
                badge.textContent = newTotalQty;
                badge.style.transform = 'translate(-50%, -50%) scale(1.3)';
                setTimeout(function() {
                    badge.style.transform = 'translate(-50%, -50%) scale(1)';
                }, 300);
            });
        }
    })
    .catch(function(err) {
        console.error('Error updating modal quantity:', err);
        btnMinus.style.pointerEvents = '';
        btnPlus.style.pointerEvents = '';
        qtyInput.style.opacity = '';
    });
}

function addToCartAndShowModalOptimistic(productId, addQty, details, btn, form) {
    var modalEl = document.getElementById('cartSuccessModal');
    if (modalEl) {
        // Populate modal elements instantly using local data
        modalEl.setAttribute('data-product-id', productId);

        var modalImg = document.getElementById('modal-product-img');
        if (modalImg) modalImg.src = details.imgUrl || '';

        var modalName = document.getElementById('modal-product-name');
        if (modalName) modalName.textContent = details.name || 'Producto';

        var modalBrand = document.getElementById('modal-product-brand');
        if (modalBrand) modalBrand.textContent = details.brand || 'WANKA';

        var modalPrice = document.getElementById('modal-product-price');
        if (modalPrice) modalPrice.textContent = details.priceText || '';

        var modalOldPrice = document.getElementById('modal-product-old-price');
        var modalDiscount = document.getElementById('modal-product-discount');
        if (modalOldPrice) {
            if (details.oldPriceText && details.oldPriceText !== details.priceText) {
                modalOldPrice.textContent = details.oldPriceText;
                modalOldPrice.style.display = 'block';
                if (modalDiscount && details.discountPercent) {
                    modalDiscount.textContent = '-' + details.discountPercent + '%';
                    modalDiscount.style.display = 'inline-block';
                }
            } else {
                modalOldPrice.style.display = 'none';
                if (modalDiscount) modalDiscount.style.display = 'none';
            }
        }

        var modalQtyInput = document.getElementById('modal-qty-input');
        var btnMinus = document.getElementById('modal-qty-minus');
        var btnPlus = document.getElementById('modal-qty-plus');

        if (modalQtyInput) {
            modalQtyInput.value = '...'; // Temporary loading indicator
            modalQtyInput.style.opacity = '0.5';
        }
        if (btnMinus) btnMinus.style.pointerEvents = 'none';
        if (btnPlus) btnPlus.style.pointerEvents = 'none';

        // Open Modal Instantly (Optimistic UX)
        openModalHelper(modalEl);
    }

    // Fire network request in the background
    fetch('/shop/cart/update_json', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            params: {
                product_id: parseInt(productId),
                add_qty: parseInt(addQty)
            }
        })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        // Restore original button state
        if (btn && btn._originalHTML) {
            btn.classList.remove('disabled');
            btn.style.opacity = '';
            btn.innerHTML = btn._originalHTML;
        }

        // Re-enable modal controls
        if (modalQtyInput) modalQtyInput.style.opacity = '';
        if (btnMinus) btnMinus.style.pointerEvents = '';
        if (btnPlus) btnPlus.style.pointerEvents = '';

        if (data && data.result && typeof data.result.cart_quantity !== 'undefined') {
            // Update header badges
            var qtyBadges = document.querySelectorAll('.my-cart-qty');
            var newTotalQty = data.result.cart_quantity;
            qtyBadges.forEach(function(badge) {
                badge.textContent = newTotalQty;
                badge.style.transform = 'translate(-50%, -50%) scale(1.3)';
                setTimeout(function() {
                    badge.style.transform = 'translate(-50%, -50%) scale(1)';
                }, 300);
            });

            // Update quantity input inside modal with actual quantity in cart
            if (modalQtyInput) {
                modalQtyInput.value = data.result.quantity || addQty;
            }
        } else {
            if (form) form.submit();
        }
    })
    .catch(function(err) {
        console.error('Error adding to cart:', err);
        if (btn && btn._originalHTML) {
            btn.classList.remove('disabled');
            btn.style.opacity = '';
            btn.innerHTML = btn._originalHTML;
        }
        if (form) form.submit();
    });
}

function openModalHelper(modalEl) {
    if (window.bootstrap && window.bootstrap.Modal) {
        var myModal = new window.bootstrap.Modal(modalEl);
        myModal.show();
    } else if (window.$ && typeof window.$.prototype.modal === 'function') {
        window.$(modalEl).modal('show');
    } else {
        // Manual fallback
        modalEl.classList.add('show');
        modalEl.style.display = 'block';
        document.body.classList.add('modal-open');

        var backdrop = document.getElementById('modal-custom-backdrop');
        if (!backdrop) {
            backdrop = document.createElement('div');
            backdrop.id = 'modal-custom-backdrop';
            backdrop.className = 'modal-backdrop fade show';
            document.body.appendChild(backdrop);
            backdrop.onclick = function() { closeModal(); };
        }

        var closeBtns = modalEl.querySelectorAll('[data-bs-dismiss="modal"], [data-dismiss="modal"]');
        closeBtns.forEach(function(btn) {
            btn.onclick = function(e) {
                e.preventDefault();
                closeModal();
            };
        });

        function closeModal() {
            modalEl.classList.remove('show');
            modalEl.style.display = 'none';
            document.body.classList.remove('modal-open');
            if (backdrop) backdrop.remove();
        }
    }
}
